//! The sync-v1 crypto vectors (`fixtures/sync-crypto-vectors.json`, generated by stash-player's `scripts/sync-fixtures.mjs`),
//! which the web player and the Android app pass too: this computer reads and writes the same bytes.

use serde_json::Value;
use stash_core::link::crypto::{
    Envelope, MAX_PLAINTEXT, aad, aes_open, b64u, data_key, gunzip, hkdf, open, seal_gz_with, token_hash, unb64,
};
use stash_core::link::keys::{
    KeyPair, open_key_envelope, pair_code, pair_info, pair_key, pair_label_key, qr_link, read_label, read_pair_answer,
};

fn vectors() -> Value {
    serde_json::from_str(include_str!("fixtures/sync-crypto-vectors.json")).unwrap()
}
fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str().unwrap_or_else(|| panic!("{k}"))
}
fn bytes(v: &Value, k: &str) -> Vec<u8> {
    unb64(s(v, k)).unwrap()
}
fn env(v: &Value) -> Envelope {
    serde_json::from_value(v.clone()).unwrap()
}
fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

#[test]
fn base64url_is_strict() {
    let v = vectors();
    for c in v["b64u"]["valid"].as_array().unwrap() {
        let b = unb64(s(c, "b64u")).unwrap();
        assert_eq!(hex(&b), s(c, "hex"));
        assert_eq!(b64u(&b), s(c, "b64u"));
    }
    for bad in v["b64u"]["invalid"].as_array().unwrap() {
        assert!(unb64(bad.as_str().unwrap()).is_err(), "{bad}");
    }
}

#[test]
fn hkdf_token_hash_and_data_keys() {
    let v = vectors();
    for c in v["hkdf"].as_array().unwrap() {
        let okm = hkdf(&bytes(c, "ikm"), &bytes(c, "salt"), &bytes(c, "info"), c["length"].as_u64().unwrap() as usize);
        assert_eq!(b64u(&okm), s(c, "okm"));
    }
    let t = &v["tokenHash"];
    assert_eq!(token_hash(&bytes(t, "token")), s(t, "hash"));
    let sp = &v["space"];
    assert_eq!(b64u(&data_key(&bytes(sp, "k"), s(sp, "spaceId"))), s(sp, "dataKey"));
    assert_eq!(b64u(&data_key(&bytes(sp, "k2"), s(sp, "spaceId"))), s(sp, "dataKey2"));
}

#[test]
fn envelopes_seal_and_open_as_the_web_and_the_app_do() {
    let v = vectors();
    let sp = &v["space"];
    for c in v["envelopes"].as_array().unwrap() {
        let name = s(c, "name");
        let key = match s(c, "key") {
            "dataKey" => bytes(sp, "dataKey"),
            "dataKey2" => bytes(sp, "dataKey2"),
            other => panic!("{name}: key {other}"),
        };
        let epoch = c["epoch"].as_i64().unwrap();
        assert_eq!(aad(s(c, "spaceId"), epoch, s(c, "place")), s(c, "aad"), "{name}");
        let sealed = seal_gz_with(&key, s(c, "spaceId"), epoch, s(c, "place"), &bytes(c, "gz"), &bytes(c, "nonce")).unwrap();
        assert_eq!(sealed, env(&c["env"]), "{name}: sealed");
        let opened = open(&key, s(c, "spaceId"), s(c, "place"), &env(&c["env"])).unwrap();
        let want: Value = serde_json::from_str(s(c, "json")).unwrap();
        assert_eq!(opened, want, "{name}: opened");
        // Another place, or another space, doesn't open.
        assert!(open(&key, s(c, "spaceId"), "elsewhere", &env(&c["env"])).is_err(), "{name}");
    }
}

#[test]
fn a_document_in_parts_opens_from_its_slices_in_order() {
    let v = vectors();
    let p = &v["parts"];
    let key = bytes(&v["space"], "dataKey");
    let mut gz = Vec::new();
    for part in p["parts"].as_array().unwrap() {
        let e = env(&part["env"]);
        assert_eq!(aad(s(p, "spaceId"), e.e, s(part, "place")), s(part, "aad"));
        let slice = aes_open(&key, &unb64(&e.n).unwrap(), s(part, "aad"), &unb64(&e.c).unwrap()).unwrap();
        assert_eq!(b64u(&slice), s(part, "slice"));
        gz.extend_from_slice(&slice);
    }
    assert_eq!(b64u(&gz), s(p, "gz"));
    let doc: Value = serde_json::from_slice(&gunzip(&gz, MAX_PLAINTEXT).unwrap()).unwrap();
    assert_eq!(doc, serde_json::from_str::<Value>(s(p, "json")).unwrap());
}

/// This computer in the browser's place: its QR, its label, Kpair from the phone's answer, the code, the answer and the reply.
#[test]
fn pairing_from_the_code_s_side() {
    let v = vectors();
    let p = &v["pairing"];
    let pair_id = s(p, "pairId");
    let secret = bytes(p, "pairSecret");
    let e_b = KeyPair::from_secret(&bytes(&p["browserEphemeral"], "d")).unwrap();
    assert_eq!(b64u(&e_b.public), s(&p["browserEphemeral"], "pub"));
    let e_p_pub = bytes(&p["phoneEphemeral"], "pub");
    assert_eq!(qr_link(pair_id, &secret, &e_b.public), s(p, "qr"));
    let label_key = pair_label_key(&secret);
    assert_eq!(b64u(&label_key), s(p, "labelKey"));

    // The browser's own label, sealed in the slot, opens and reads.
    let l = &p["label"];
    let doc = open(&label_key, "pair", s(l, "place"), &env(&l["env"])).unwrap();
    let shower_id = s(l, "place").strip_prefix("label:").unwrap();
    let shower = read_label(&doc, shower_id).unwrap();
    assert_eq!(b64u(&shower.public), s(p, "browserDevicePub"));

    assert_eq!(b64u(&e_b.ecdh(&e_p_pub).unwrap()), s(p, "shared"));
    assert_eq!(pair_info(pair_id, &e_b.public, &e_p_pub, shower_id, &shower.public), s(p, "info"));
    let kpair = pair_key(&e_b, &e_p_pub, &secret, pair_id, shower_id, &shower.public).unwrap();
    assert_eq!(b64u(&kpair), s(p, "kpair"));
    let sas = &p["sas"];
    let code = pair_code(&kpair);
    assert_eq!(code, sas.as_str().map(str::to_string).unwrap_or_else(|| s(sas, "code").to_string()));

    let a = &p["answer"];
    let (phone, space) = read_pair_answer(&open(&kpair, "pair", s(a, "place"), &env(&a["env"])).unwrap()).unwrap();
    assert_eq!(phone.kind, "phone");
    assert_eq!(b64u(&phone.public), s(p, "phoneDevicePub"));
    let space = space.expect("the phone names a space");
    assert_eq!(space.id, s(&v["space"], "spaceId"));
    let r = &p["reply"];
    let reply = open(&kpair, "pair", s(r, "place"), &env(&r["env"])).unwrap();
    assert_eq!(reply["kind"], "stash-pair-reply");
    // The reply this computer writes seals the same way.
    let sealed = seal_gz_with(&kpair, "pair", 0, s(r, "place"), &bytes(r, "gz"), &bytes(r, "nonce")).unwrap();
    assert_eq!(sealed, env(&r["env"]));
}

#[test]
fn a_key_envelope_after_a_rotation_opens_with_this_device_s_key_and_proves_itself() {
    let v = vectors();
    let r = &v["rotation"];
    let device = KeyPair::from_secret(&bytes(&r["device"], "d")).unwrap();
    assert_eq!(b64u(&device.public), s(&r["device"], "pub"));
    let e = env(&r["env"]);
    let (k, epoch, members) =
        open_key_envelope(&e, s(r, "spaceId"), s(r, "deviceId"), &device, &bytes(r, "prevKey"), r["prevEpoch"].as_i64().unwrap())
            .unwrap();
    assert_eq!(b64u(&k), s(r, "newKey"));
    assert_eq!(epoch, r["epoch"].as_i64().unwrap());
    assert_eq!(members, r["members"].as_array().unwrap().iter().map(|m| m.as_str().unwrap().to_string()).collect::<Vec<_>>());
    // Under another previous key the proof fails; for another epoch it isn't tried.
    assert!(open_key_envelope(&e, s(r, "spaceId"), s(r, "deviceId"), &device, &[9u8; 32], r["prevEpoch"].as_i64().unwrap()).is_err());
    assert!(open_key_envelope(&e, s(r, "spaceId"), s(r, "deviceId"), &device, &bytes(r, "prevKey"), 7).is_err());
}
